'use strict';
const crypto=require('node:crypto'),P=require('./policy.cjs');
const TREE='55df9c452dff405ce4805b4f9e3dcee3a09f7202',COUNT=257,MAX=32*1024*1024;
function safePath(s){return typeof s==='string'&&s.length<240&&s.split('/').every(x=>x&&x!=='.'&&x!=='..')&&!/[\\\x00-\x1f:]/.test(s)&&!/(^|\/)(node_modules|\.git|\.env|credentials\.json)(\/|$)/i.test(s);}
function manifest(v){if(!P.exact(v,['kind','nativeSource','backendSource','mobileTree','files'])||v.kind!=='PUBLIC_TRACKED_IOS21_SOURCE_MANIFEST'||v.nativeSource!==P.SOURCE||v.backendSource!==P.BACKEND_SOURCE||v.mobileTree!==TREE||!Array.isArray(v.files)||v.files.length!==COUNT)P.fail();let previous='',total=0;for(const r of v.files){if(!P.exact(r,['path','mode','gitBlob','bytes','sha256'])||!safePath(r.path)||r.path<=previous||!['100644','100755'].includes(r.mode)||!P.GIT.test(r.gitBlob)||!P.SHA.test(r.sha256)||!Number.isSafeInteger(r.bytes)||r.bytes<0||(total+=r.bytes)>MAX)P.fail();previous=r.path;}return v;}
function verifyFiles(v,files){manifest(v);if(!Array.isArray(files)||files.length!==COUNT)P.fail();return files.map((f,i)=>{const r=v.files[i];if(!P.exact(f,['path','base64'])||f.path!==r.path||typeof f.base64!=='string'||f.base64.length>MAX*2)P.fail();const b=Buffer.from(f.base64,'base64');if(b.toString('base64')!==f.base64||b.length!==r.bytes||P.sha(b)!==r.sha256||crypto.createHash('sha1').update(Buffer.from('blob '+b.length+'\0')).update(b).digest('hex')!==r.gitBlob)P.fail();return {path:r.path,mode:r.mode,bytes:b};});}
function overlay(rows){const f=rows.find(f=>f.path==='app.config.ts');if(!f)P.fail();const s=f.bytes.toString('utf8');if(!Buffer.from(s).equals(f.bytes)||s.split("buildNumber: '13'").length!==2||s.split("bundleIdentifier: '"+P.BUNDLE+"'").length!==2)P.fail();return rows.map(r=>({...r,bytes:r===f?Buffer.from(s.replace("buildNumber: '13'","buildNumber: '21'")):r.bytes}));}
function parseGit(v,raw){manifest(v);if(!Buffer.isBuffer(raw)||raw.length>MAX+65536)P.fail();const files=[];let at=0;for(const r of v.files){const end=raw.indexOf(10,at);if(end<0||end-at>100||raw.subarray(at,end).toString('ascii')!==r.gitBlob+' blob '+r.bytes)P.fail();at=end+1;if(at+r.bytes>=raw.length)P.fail();const b=raw.subarray(at,at+r.bytes);if(P.sha(b)!==r.sha256||crypto.createHash('sha1').update(Buffer.from('blob '+b.length+'\0')).update(b).digest('hex')!==r.gitBlob||raw[at+r.bytes]!==10)P.fail();files.push({path:r.path,base64:b.toString('base64')});at+=r.bytes+1;}if(at!==raw.length)P.fail();verifyFiles(v,files);return files;}
function gitFiles(v,readGit){manifest(v);if(typeof readGit!=='function')P.fail();const raw=readGit(P.SOURCE,v.files.map(r=>'mobile/'+r.path));try{return parseGit(v,raw);}finally{raw?.fill(0);}}
module.exports={TREE,COUNT,MAX,safePath,manifest,verifyFiles,overlay,parseGit,gitFiles};
